  location, mileage_limit, host_name, host_rating, rating, review_count, is_available, is_popular, is_featured) values
  ('car-cadillac-escalade-2025', 'Cadillac Escalade 2025', 'Cadillac', 'Escalade Premium Luxury Platinum', 2025, 'Luxury', 700000, 110000, 420, 6.1, 180, 'Automatic', 'Petrol', 7, 5, 'Black Raven', '/images/fleet/cadillac-escalade-2025.jpg', array['/images/fleet/cadillac-escalade-2025.jpg']::text[], 'The newest Escalade: a 6.2-litre V8, a 55-inch curved OLED display across the dashboard, and executive-class comfort for seven. Ideal for VIP arrivals, weddings and high-profile visits.', array['6.2L V8, 10-speed automatic', '55-inch curved OLED dashboard display', 'AKG Studio Reference sound', 'Massaging, heated and ventilated front seats', 'Air Ride adaptive suspension', 'Super Cruise hands-free driving assist', 'Rear-seat entertainment', 'Third-row seating for 7']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Calabar, Cross River State', '250 km / day', 'Aurevon Fleet', 5, 5, 0, true, true, true),
  ('car-cadillac-escalade', 'Cadillac Escalade', 'Cadillac', 'Escalade ESV Premium Luxury', 2022, 'Luxury', 550000, 85000, 420, 6.3, 180, 'Automatic', 'Petrol', 7, 5, 'Satin Steel Metallic', '/images/fleet/cadillac-escalade.jpg', array['/images/fleet/cadillac-escalade.jpg']::text[], 'The extended-wheelbase Escalade ESV: commanding presence, generous luggage space behind the third row and a quiet, cushioned ride for long journeys and airport transfers.', array['6.2L V8, 10-speed automatic', 'Extended wheelbase with extra cargo space', 'Curved OLED display', 'AKG sound system', 'Heated and ventilated seats', 'Magnetic Ride Control', 'Rear-seat entertainment', 'Seats 7']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Victoria Island, Lagos', '250 km / day', 'Aurevon Fleet', 5, 5, 0, true, false, false),
  ('car-mercedes-gle450', 'Mercedes-Benz GLE 450 2026', 'Mercedes-Benz', 'GLE 450 4MATIC', 2026, 'Luxury', 450000, 70000, 375, 5.7, 250, 'Automatic', 'Petrol', 5, 5, 'Sodalite Blue Metallic', '/images/fleet/mercedes-gle450.jpg', array['/images/fleet/mercedes-gle450.jpg']::text[], 'The latest GLE 450 4MATIC pairs a smooth inline-six mild-hybrid engine with Mercedes’ calm, refined cabin — a polished choice for executives and business travel.', array['3.0L inline-6 with EQ Boost mild hybrid', '4MATIC all-wheel drive', 'MBUX dual widescreen displays', 'Burmester surround sound', 'Panoramic sunroof', 'Heated and ventilated seats', 'Active parking assist with 360° camera', 'Ambient lighting']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Lekki, Lagos', '250 km / day', 'Aurevon Fleet', 5, 5, 0, true, true, false),
  ('car-lexus-gx460', 'Lexus GX 460', 'Lexus', 'GX 460 Premium', 2023, 'Luxury', 300000, 50000, 301, 8.1, 175, 'Automatic', 'Petrol', 7, 5, 'Starfire Pearl', '/images/fleet/lexus-gx460.jpg', array['/images/fleet/lexus-gx460.jpg']::text[], 'Lexus comfort on a tough body-on-frame chassis: a proven V8, full-time four-wheel drive and adjustable suspension that copes with any road between Calabar and Lagos.', array['4.6L V8', 'Full-time 4WD with locking centre differential', 'Kinetic Dynamic Suspension', 'Leather seats, heated and ventilated', 'Mark Levinson audio', 'Third row for 7', 'Multi-terrain monitor', 'Sunroof']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Calabar, Cross River State', '300 km / day', 'Aurevon Fleet', 5, 5, 0, true, false, false),
  ('car-mercedes-vclass', 'Mercedes-Benz V-Class 250', 'Mercedes-Benz', 'V 250 Avantgarde', 2022, 'Luxury', 350000, 55000, 190, 9.7, 200, 'Automatic', 'Diesel', 7, 5, 'Selenite Grey', '/images/fleet/mercedes-vclass.jpg', array['/images/fleet/mercedes-vclass.jpg']::text[], 'A first-class lounge on wheels: individual captain’s chairs, sliding doors on both sides and room for luggage. Perfect for group airport transfers, wedding parties and corporate shuttles.', array['Individual captain’s chairs', 'Electric sliding doors on both sides', 'Rear climate control', 'Large luggage space', 'Leather upholstery', 'Reversing camera', 'USB charging for every row', 'Seats 7']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Ikeja, Lagos', '300 km / day', 'Aurevon Fleet', 5, 5, 0, true, false, false),
  ('car-toyota-granvia', 'Toyota Granvia', 'Toyota', 'Granvia Premium', 2023, 'Luxury', 280000, 45000, 174, 12.5, 170, 'Automatic', 'Diesel', 8, 5, 'White Pearl', '/images/fleet/toyota-granvia.jpg', array['/images/fleet/toyota-granvia.jpg']::text[], 'Toyota’s premium people-carrier: quiet, spacious and dependable, with reclining seats and easy access through wide sliding doors. Great for family trips and group travel.', array['Seats 8 with reclining middle row', 'Wide power sliding doors', 'Dual-zone and rear air conditioning', 'Large luggage area', 'Reversing camera', 'Toyota Safety Sense', 'USB charging', 'Smooth 2.8L turbo-diesel']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Calabar, Cross River State', '300 km / day', 'Aurevon Fleet', 5, 5, 0, true, false, false),
  ('car-toyota-lc300', 'Toyota Land Cruiser LC300', 'Toyota', 'Land Cruiser 300 VXR', 2024, 'SUV', 450000, 70000, 409, 6.7, 210, 'Automatic', 'Petrol', 7, 5, 'Pearl White', '/images/fleet/toyota-lc300.jpg', array['/images/fleet/toyota-lc300.jpg']::text[], 'The legendary Land Cruiser, now with a twin-turbo V6. Unmatched reliability and comfort on every surface — the go-to choice for long-distance and official travel in Nigeria.', array['3.5L twin-turbo V6, 10-speed automatic', 'Full-time 4WD with Multi-Terrain Select', 'Leather seats, heated and ventilated', 'JBL premium sound', '360° camera', 'Third row for 7', 'Cool box in centre console', 'Toyota Safety Sense']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Calabar, Cross River State', '300 km / day', 'Aurevon Fleet', 5, 5, 0, true, true, true),
  ('car-chevrolet-tahoe', 'Chevrolet Tahoe 2023', 'Chevrolet', 'Tahoe Premier', 2023, 'SUV', 350000, 55000, 355, 7.4, 180, 'Automatic', 'Petrol', 8, 5, 'Satin Steel', '/images/fleet/chevrolet-tahoe.jpg', array['/images/fleet/chevrolet-tahoe.jpg']::text[], 'Full-size American SUV with seating for eight and real luggage space even with every seat in use. Comfortable, powerful and ideal for families and teams on the move.', array['5.3L V8, 10-speed automatic', 'Seats 8 across three rows', 'Power-folding third row', 'Bose premium audio', 'Heated and ventilated front seats', 'Wireless Apple CarPlay and Android Auto', 'Rear camera mirror', 'Hands-free power liftgate']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Victoria Island, Lagos', '300 km / day', 'Aurevon Fleet', 5, 5, 0, true, true, false),
  ('car-toyota-prado', 'Toyota Land Cruiser Prado', 'Toyota', 'Land Cruiser Prado 250 VX', 2024, 'SUV', 250000, 40000, 278, 8.5, 175, 'Automatic', 'Petrol', 7, 5, 'White Pearl', '/images/fleet/toyota-prado.jpg', array['/images/fleet/toyota-prado.jpg']::text[], 'The all-new Prado: rugged, roomy and easy to drive, with modern safety tech and the go-anywhere ability Land Cruisers are known for. A favourite for business and family trips alike.', array['2.4L turbo, 8-speed automatic', 'Full-time 4WD', '12.3-inch touchscreen', 'Wireless Apple CarPlay and Android Auto', 'Third row for 7', 'Multi-terrain monitor', 'Toyota Safety Sense', 'Leather-trimmed seats']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Calabar, Cross River State', '300 km / day', 'Aurevon Fleet', 5, 5, 0, true, true, false),
  ('car-toyota-hilux', 'Toyota Hilux Adventure 2024', 'Toyota', 'Hilux Adventure Double Cab 4x4', 2024, 'SUV', 200000, 35000, 201, 10.7, 175, 'Automatic', 'Diesel', 5, 4, 'Emotional Red', '/images/fleet/toyota-hilux.jpg', array['/images/fleet/toyota-hilux.jpg']::text[], 'The Hilux Adventure double-cab pickup: tough, economical and built for rough roads, site visits and weekend adventures, with room for five and a full load bed.', array['2.8L turbo-diesel, 6-speed automatic', 'Part-time 4x4 with rear diff lock', 'Double cab, seats 5', 'Load bed with liner', 'Touchscreen with Apple CarPlay and Android Auto', 'Reversing camera', 'Hill-start assist and downhill assist', 'Side steps and roof rails']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Calabar, Cross River State', '300 km / day', 'Aurevon Fleet', 5, 5, 0, true, true, false),
  ('car-toyota-rav4', 'Toyota RAV4 2025', 'Toyota', 'RAV4 XLE', 2025, 'SUV', 150000, 25000, 203, 8.4, 190, 'Automatic', 'Petrol', 5, 5, 'Silver Sky', '/images/fleet/toyota-rav4.jpg', array['/images/fleet/toyota-rav4.jpg']::text[], 'A compact, efficient SUV that’s easy to park and comfortable on longer drives — our most affordable way to travel in style around Calabar and Lagos.', array['2.5L petrol, 8-speed automatic', 'All-wheel drive', 'Apple CarPlay and Android Auto', 'Toyota Safety Sense', 'Dual-zone climate control', 'Reversing camera', 'Roof rails', 'Generous boot space']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Lekki, Lagos', '300 km / day', 'Aurevon Fleet', 5, 5, 0, true, false, false)
